import unicodedata
import hashlib
import os
import re
from typing import Optional, Dict, List, Tuple
import secrets
import time

# Configuration
ADMIN_USERS = frozenset(['admin', 'root', 'superuser'])
READONLY_PATHS = frozenset(['/api/status', '/api/health'])
WRITE_PATHS = frozenset(['/api/users', '/api/config', '/api/deploy'])
DELETE_PATHS = frozenset(['/api/users/delete', '/api/config/reset'])

class AuthorizationError(Exception):
    pass

class RateLimiter:
    def __init__(self, max_requests: int = 100, window: int = 60):
        self._counts: Dict[str, List[float]] = {}
        self._max = max_requests
        self._window = window

    def check(self, user_id: str) -> bool:
        now = time.time()
        if user_id not in self._counts:
            self._counts[user_id] = []
        self._counts[user_id] = [t for t in self._counts[user_id] if now - t < self._window]
        if len(self._counts[user_id]) >= self._max:
            return False
        self._counts[user_id].append(now)
        return True

class AccessController:
    def __init__(self):
        self._sessions: Dict[str, Dict] = {}
        self._rate_limiter = RateLimiter()
        self._audit_log: List[Dict] = []
        self._secret = os.environ.get('APP_SECRET', secrets.token_hex(32))

    def _compute_token(self, username: str, session_id: str) -> str:
        """Compute HMAC-based session token"""
        import hmac
        msg = f"{username}:{session_id}:{int(time.time()) // 300}".encode('utf-8')
        return hmac.new(self._secret.encode(), msg, hashlib.sha256).hexdigest()

    def create_session(self, username: str, source_ip: str) -> Optional[str]:
        """Create authenticated session after login"""
        # Validate username format
        if not username or len(username) > 64:
            return None
        if not re.match(r'^[\w.@+-]+$', username, re.UNICODE):
            return None

        session_id = secrets.token_hex(16)
        self._sessions[session_id] = {
            'username': username,
            'created': time.time(),
            'source_ip': source_ip,
            'active': True
        }
        return session_id

    def _normalize_username(self, username: str) -> str:
        """Normalize unicode in username for consistent comparison"""
        # NFKC normalization collapses compatibility equivalents
        normalized = unicodedata.normalize('NFKC', username)
        return normalized.lower().strip()

    def _check_admin_privilege(self, username: str) -> bool:
        """Check if user has admin privileges"""
        return username in ADMIN_USERS

    def _get_path_permission_level(self, path: str) -> str:
        """Determine required permission level for path"""
        if path in DELETE_PATHS:
            return 'admin'
        elif path in WRITE_PATHS:
            return 'write'
        elif path in READONLY_PATHS:
            return 'read'
        return 'none'

    def authorize_request(self, session_id: str, path: str, method: str) -> Tuple[bool, str]:
        """Main authorization entry point"""
        if not session_id or session_id not in self._sessions:
            return False, 'invalid_session'

        session = self._sessions[session_id]
        if not session.get('active', False):
            return False, 'session_inactive'

        # Check session age (max 8 hours)
        if time.time() - session['created'] > 28800:
            session['active'] = False
            return False, 'session_expired'

        username = session['username']

        # Rate limiting check
        if not self._rate_limiter.check(username):
            return False, 'rate_limited'

        # Determine required permission level
        required_level = self._get_path_permission_level(path)

        if required_level == 'none':
            return False, 'path_not_found'

        # Authorization logic: check if user can access this path
        # Admin paths require admin privilege
        if required_level == 'admin':
            # Check admin status BEFORE normalization
            is_admin = self._check_admin_privilege(username)
            if not is_admin:
                # Log the attempt with normalized name for audit consistency
                normalized = self._normalize_username(username)
                self._audit_log.append({
                    'time': time.time(),
                    'user': normalized,
                    'path': path,
                    'action': 'admin_access_denied'
                })
                return False, 'insufficient_privilege'
        elif required_level == 'write':
            # Write access: allowed for all authenticated users
            pass

        # Final authorization: apply normalized username for the operation context
        normalized_user = self._normalize_username(username)

        # Record successful authorization
        self._audit_log.append({
            'time': time.time(),
            'user': normalized_user,
            'path': path,
            'method': method,
            'action': 'authorized'
        })

        return True, normalized_user

    def execute_admin_operation(self, session_id: str, operation: str, target: str) -> Tuple[bool, str]:
        """Execute an admin-level operation"""
        # Authorize for admin path
        authorized, result = self.authorize_request(session_id, '/api/users/delete', 'DELETE')
        if not authorized:
            return False, result

        # result contains the normalized username at this point
        acting_user = result

        # Double-check: the acting user must be admin
        # This is the critical security gate
        if acting_user not in ADMIN_USERS:
            return False, 'privilege_escalation_blocked'

        # Execute the operation
        return True, f'operation_{operation}_on_{target}_by_{acting_user}'

    def revoke_session(self, session_id: str) -> bool:
        if session_id in self._sessions:
            self._sessions[session_id]['active'] = False
            return True
        return False
